INSERT OR IGNORE INTO processos (id, clienteId, numeroCnj, tribunal, comarca, vara, tipoAcao, natureza, classeProcessual, assunto, faseAtual, statusProcesso, valorCausa, dataDistribuicao, dataSentenca, juiz, prioridade, segredoJustica, poloAtivo, poloPassivo, advogadoAutor, resumoSentenca, valorCondenacao, danosMorais, danosMateriais, restituicao, honorariosPerc, honorariosValor, tutelaTipo, tutelaStatus, tutelaDescricao, pdfStorageKey, pdfUrl, textoExtraido, createdAt, updatedAt, processoOrigemId, tipoVinculo) VALUES (210003, 180004, '5365470-18.2024.8.09.0011', 'TJ-GO', 'Aparecida de Goiânia', 'UPJ VARAS CÍVEIS - 1ª a 6ª', 'AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', 'Cível - Consignado', NULL, NULL, 'Fase Recursal (Apelação)', 'Sentença Procedente com Recursos Pendentes', '495462.93', NULL, NULL, NULL, NULL, 0, 'CARLOS ANDRADE DOS SANTOS', 'BANCO SAFRA S.A., BANCO SANTANDER (BRASIL) S.A., BANCO BRADESCO S.A.', NULL, 'JULGO PROCEDENTES os pedidos. Declarada ilegalidade das parcelas excedentes a 35% da margem consignável. Determinada adequação das prestações. Proibida inscrição em cadastros negativos. Honorários 10% do proveito econômico.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-13 23:40:25.000', '2026-03-17 04:33:28.000', NULL, NULL);
