INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (1, 1, '26/05/2025', 'Petição Inicial', '[Ev.1] Ajuizamento da Ação de Obrigação de Fazer com pedido de Tutela Antecipada de Urgência, visando a readequação de empréstimos consignados para o limite de 35% da renda líquida do autor.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (2, 2, '18/09/2024', 'Petição Inicial - Execução de Título Extrajudicial', '[Ev.1] Ajuizamento de execução de título extrajudicial (Cédula de Crédito Bancário) pelo BANCO BRADESCO S.A em face de ARIEL ANSELMO DE OLIVEIRA, no valor de R$ 301.157,70.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (3, 3, NULL, 'Sentença (Autos Principais)', '[Ev.50] Sentença favorável ao exequente nos autos principais (5890301-69.2024.8.09.0174), acolhendo Exceção de Pré-Executividade e condenando o executado à repetição de indébito em dobro.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (4, 3, NULL, 'Embargos de Declaração (Autos Principais)', '[Ev.63] Embargos de declaração para aplicar o indébito em dobro, integrando a sentença.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (5, 3, NULL, 'Recurso de Apelação (Autos Principais)', '[Ev.68] Banco Bradesco interpôs Recurso de Apelação contra a decisão dos embargos de declaração.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (6, 3, '02/10/2025', 'Petição Inicial de Cumprimento Provisório', '[Ev.1] Requerimento de CUMPRIMENTO PROVISÓRIO DE SENTENÇA com base na sentença favorável nos autos principais.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (7, 3, '02/10/2025', 'Processo Distribuído', '[Ev.2] Processo distribuído por dependância para a UPJ Varas Cíveis: 1ª e 2ª de Senador Canedo.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (8, 3, '02/10/2025', 'Autos Conclusos', '[Ev.3] Autos conclusos para análise do juiz.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (9, 3, '02/10/2025', 'Certidão Expedida', '[Ev.4] Certidão de conexão emitida, identificando processos relacionados.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (10, 3, '02/10/2025', 'Juntada de Petição', '[Ev.5] Juntada de petição de manifestação acerca da certidão de conexão e juntada de procuração.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (11, 4, '21/05/2025', 'Outorga de Procuração', 'A parte autora O.J.S COMÉRCIO E SERVIÇOS LTDA outorga procuração ad judicia e ad extra ao advogado para representá-la no processo contra a Cooperativa de Crédito.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (12, 4, '17/03/2025', 'Intimação Extrajudicial para Constituição em Mora', 'Expedição de intimação extrajudicial, a requerimento do Registro de Imóveis, para constituir os devedores em mora referente ao débito de R$ 34.039,08. As certidões de notificação são datadas de 31/03/2025 e 01/04/2025.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (13, 4, '15/08/2025', 'Nota de Esclarecimento do Cartório', 'O Registro de Imóveis e Tabelionato 1º de Notas de Palmeiras de Goiás emite nota informando a impossibilidade de receber o pagamento do débito por ter expirado o prazo legal de 15 dias após a intimação para purgação da mora.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (14, 4, '18/08/2025', 'Petição Inicial', '[Ev.1] Ajuizamento da Ação Cautelar de Tutela de Urgência Antecedente, distribuída para a 1ª Vara Cível da Comarca de Palmeiras de Goiás, visando a suspensão do procedimento de consolidação da propriedade do imóvel dado em garantia.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (15, 5, '10/04/2024', 'Ajuizamento de Ação de Repactuação de Dívida', 'Ajuizamento da Ação de Repactuação de Dívida (Processo nº 5274950-86.2024.8.09.0051) em desfavor dos bancos credores para readequar os empréstimos consignados à margem legal.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (16, 5, '11/04/2024', 'Decisão Liminar', 'Concessão de tutela de urgência nos autos da Ação de Repactuação de Dívida, determinando a readequação dos descontos e a suspensão da exigibilidade dos pagamentos excedentes.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (17, 5, '25/04/2024', 'Ciência da Decisão', '[Ev.20] O Banco Bradesco teve ciência da decisão liminar que suspendeu os descontos.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (18, 5, '20/12/2024', 'Ajuizamento da Ação de Execução', 'Ajuizamento da Ação de Execução de Título Extrajudicial (Processo nº 6151759-84.2024.8.09.0051) pelo Banco Bradesco.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (19, 5, '25/08/2025', 'Publicação de Decisão Interlocutória', '[Ev.17] Publicação da decisão interlocutória que rejeitou a exceção de pré-executividade apresentada pela cliente na ação de execução.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (20, 5, '08/09/2025', 'Petição de Agravo de Instrumento', '[Ev.1] Interposição de Recurso de Agravo de Instrumento com pedido de antecipação da tutela recursal contra a decisão que rejeitou a exceção de pré-executividade.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (21, 5, '08/09/2025', 'Distribuição de Recurso', '[Ev.2] O Agravo de Instrumento foi distribuído para a 9ª Câmara Cível, sob a relatoria do DESEMBARGADOR FERNANDO DE CASTRO MESQUITA.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (22, 5, '08/09/2025', 'Autos Conclusos', '[Ev.3] Os autos do Agravo de Instrumento foram conclusos para análise do relator.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (23, 6, '21/02/2024', 'Petição Inicial', '[Ev.1] Ação declaratória de inexistência de débito com pedido de tutela antecipada de urgência, distribuída em 21/02/2024.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (24, 6, '12/12/2023', 'Procuração Ad Judicia', 'Outorga de poderes aos advogados para representação no processo.', '2026-03-11 15:04:18.000');
