INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (26, 7, '14/03/2024', 'Petição Inicial', '[Ev.1] Ação de Obrigação de Fazer com Pedido de Tutela Antecipada de Urgência, buscando a readequação de empréstimos consignados para que não ultrapassem 35% dos proventos líquidos da autora.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (27, 7, '14/03/2024', 'Distribuição', 'O processo foi distribuído para a Vara Cível da Comarca de Bom Jesus de Goiás.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (28, 7, '14/03/2024', 'Assinatura Digital de Documento', 'Documento assinado e publicado digitalmente pelo advogado Paulo da Silva Melo Filho.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (29, 8, '13/01/2025', 'Petição Inicial', '[Ev.1] Ação de Cobrança proposta por BANCO BRADESCO S/A em face de ANA TEONILA FAGUNDES DA CUNHA, referente a um contrato de crédito em conta corrente no valor de R$ 130.709,13.', '2026-03-11 15:04:18.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30, 8, '16/10/2021', 'Substabelecimento', 'Substabelecimento com reserva de iguais poderes na pessoa dos advogados ALESSANDRO ALCANTARA COUCEIRO, JAIME ANTONIO MARTINS, JOSÉ EDUARDO SESCHI, JOSÉ LUCIO CICONELLI, WILLIAM SALZANO.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (31, 9, '12/05/2025', 'Petição Inicial', '[Ev.1] Ajuizamento da Ação de Obrigação de Fazer com Pedido de Tutela Antecipada de Urgência para readequação dos empréstimos consignados ao limite de 35% dos proventos líquidos da autora.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (32, 10, '06/05/2025', 'Petição Inicial', '[Ev.1] Ação de Repactuação de Dívidas com Pedido de Tutela Antecipada de Urgência, com base na Lei do Superendividamento, proposta por Natalicio Luiz da Costa em face de Banco Inter S.A, Caixa Econômica Federal e Banco Santander (Brasil) S.A. O autor alega que os empréstimos consignados ultrapassam a margem legal de 35%, comprometendo sua subsistência.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (33, 11, '01/11/2023', 'Petição Inicial', '[Ev.1] Ação de Cumprimento de Obrigação de Fazer com Pedido de Antecipação dos Efeitos da Tutela Específica, proposta por Glayson Charlles Rezende Reis em face do Banco Bradesco S.A., buscando o desbloqueio de R$ 487.150,30 em sua conta, valor oriundo de um empréstimo consignado. O autor alega que o banco bloqueou o valor indevidamente, apesar de as parcelas do empréstimo estarem sendo descontadas de seu contracheque.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (34, 12, '17/06/2025', 'Petição Inicial', '[Ev.1] Ajuizamento da Ação de Obrigação de Fazer com pedido de Tutela Antecipada de Urgância, visando a readequação dos descontos de empréstimos consignados para o limite de 35% dos proventos líquidos da autora.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (35, 12, '17/06/2025', 'Distribuição', 'Processo distribuído para a 6ª Câmara Cível do Tribunal de Justiça do Estado de Goiás.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (36, 12, '27/02/2026', 'Petição Enviada', 'Juntada de petição intermediária pelo advogado da parte autora.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (37, 13, NULL, 'Ação Monitória', 'Ação Monitória ajuizada pela Executada (BANCO DO BRASIL S.A.) em face de Veraneide Soares Campos Lucy, visando o recebimento de R$ 263.003,12.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (38, 13, NULL, 'Sentença', '[Ev.27] A r. sentença proferida no evento de nº. 27, julgou IMPROCEDENTE o pedido inicial e condenou a instituição financeira ao pagamento de honorários advocatícios sucumbenciais, fixados em 15% (quinze por cento) sobre o valor atualizado da causa.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (39, 13, NULL, 'Acórdão', '[Ev.80] O v. acórdão proferido no evento de nº. 80, por sua vez, negou provimento a ambos os recursos e, em atenção ao disposto no art. 85, §11, do CPC, majorou os honorários advocatícios sucumbenciais para 20% (vinte por cento) sobre o valor atualizado da causa.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (40, 13, NULL, 'Cumprimento Definitivo de Sentença', 'Inaugurado o presente Cumprimento Definitivo de Sentença por VERANEIDE SOARES CAMPOS LUCY para requerer o pagamento dos honorários advocatícios de sucumbência no valor de R$ 52.600,62.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (41, 15, '20/12/2024', 'Petição Inicial', '[Ev.1] Ajuizamento da Ação de Execução de Título Extrajudicial pelo BANCO BRADESCO S/A em face de ANA TEONILA FAGUNDES DA CUNHA, com a juntada de documentos e planilha de débito. O documento foi assinado e publicado digitalmente.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (42, 15, '08/01/2025', 'Despacho', 'Despacho inicial determinando a citação da parte executada para pagar a dívida no prazo de 3 dias, sob pena de penhora de bens. Fixados honorários advocatícios em 10% sobre o valor da execução.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (43, 16, '25/05/2025', 'Sentença', '[Ev.27] Sentença proferida no processo, conforme mencionado no título executivo (mov. 27).', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (44, 16, '26/01/2026', 'Acórdão', '[Ev.80] Acórdão proferido pelo TJ-GO (9ª Câmara Cível), conforme mencionado no título executivo (mov. 80).', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (45, 16, '27/02/2026', 'Petição de Cumprimento de Sentença', 'Petição para início do Cumprimento Definitivo de Sentença para pagamento dos honorários advocatícios sucumbenciais, com base na planilha de atualização de débito.', '2026-03-11 15:04:19.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (47, 30003, '14/11/2025', 'Petição de Cumprimento Provisório', '[Ev.1] Protocolo do Cumprimento Provisório de Sentença por dependência ao processo nº 5380169-54.2025.8.09.0051, para execução de honorários advocatícios de sucumbência no valor de R$ 41.049,00.', '2026-03-11 15:19:05.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30001, 30002, '2025-05-16', 'Petição Inicial', 'Ação de Obrigação de Fazer c/c Tutela Antecipada de Urgência ajuizada por Leonardo Rosa Correia em face de Banco Inter, Banco Pan e Itaú Unibanco', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30002, 30002, '2025-05-16', 'Tutela Antecipada Deferida', 'Deferida tutela de urgência determinando readequação dos empréstimos consignados ao limite de 35% da remuneração líquida, com multa de R$ 1.000,00/dia por descumprimento', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30003, 30002, '2025-10-21', 'SENTENÇA - Procedência Parcial', 'Julgados parcialmente procedentes os pedidos. Confirmada tutela antecipada com ajustes. Readequação definitiva dos empréstimos. Honorários de 10% sobre valor da causa (R$ 405.886,42), rateados 1/3 para cada réu', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30004, 30002, '2025-10-29', 'Embargos de Declaração - Banco Inter', 'Banco Inter opõe ED pedindo ofício ao órgão pagador e honorários sobre valor da condenação em vez do valor da causa', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30005, 30002, '2025-11-01', 'Embargos de Declaração - Banco Itaú', 'Banco Itaú opõe ED sobre honorários e ofício', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30006, 30002, '2025-12-15', 'Decisão - Embargos de Declaração', 'ED do Itaú REJEITADOS. ED do Inter ACOLHIDOS PARCIALMENTE apenas para determinar bloqueio de margem consignável para novas contratações', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30007, 30002, '2026-01-19', 'Depósito Judicial - Itaú', 'Banco Itaú deposita voluntariamente R$ 13.687,03 (cota-parte 1/3 dos honorários sucumbenciais). Conta judicial nº 5000120844906', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30008, 30002, '2026-01-27', 'Pedido de Alvará - Honorários', 'Advogado Paulo Melo requer expedição de alvará para levantamento dos R$ 13.687,03 depositados pelo Itaú a título de honorários sucumbenciais', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30009, 30002, '2026-01-30', 'Apelação - Banco Inter', 'Banco Inter interpõe apelação pedindo reforma total da sentença. Questiona aplicabilidade da legislação estadual, valor da causa e honorários', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30010, 30002, '2026-01-30', 'INDEFERIMENTO do Alvará', 'Juiz indefere pedido de alvará. Fundamenta na pendência de apelação do Banco Inter que poderia alterar ônus sucumbencial', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30011, 30002, '2026-02-04', 'Embargos de Declaração - Advogado', 'Advogado opõe ED contra indeferimento do alvará, com pedido de efeitos infringentes, fundamentando na natureza alimentar dos honorários e preclusão lógica do Itaú', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30012, 30002, '2026-02-16', 'Contrarrazões aos ED - Banco Inter', 'Banco Inter apresenta contrarrazões aos embargos do advogado, alegando caráter protelatório', '2026-03-13 10:58:39.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (30013, 30002, '2026-03-02', 'Embargos REJEITADOS', 'Juiz rejeita embargos do advogado, mantém indeferimento do alvará. Determina intimação para contrarrazões à apelação do Banco Inter (15 dias úteis)', '2026-03-13 10:58:39.000');
