INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (90011, 120019, '2025-07-31', 'Petição de Cumprimento Provisório de Sentença protocolada - Honorários R$ 52.557,18', 'Petição', '2026-03-13 23:40:25.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (90012, 120019, '2025-07-31', 'Planilha de débito atualizada anexada - Valor atualizado R$ 525.571,85', 'Petição', '2026-03-13 23:40:25.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120001, 360003, '2026-02-27', 'Petição Enviada', 'Petição inicial do cumprimento provisório de sentença com planilha de atualização de débito. Honorários sucumbenciais de 10% sobre valor atualizado da causa (R$ 54.559,76).', '2026-03-17 23:23:54.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120002, 360003, '2026-02-27', 'Processo Distribuído', 'Distribuído para FILIPE AUGUSTO CAETANO SANCHO - Vara Cível da Comarca de Rialma (Dependente do processo 5277803-07.2024.8.09.0136).', '2026-03-17 23:23:54.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120003, 360003, '2026-02-27', 'Autos Conclusos', 'Autos conclusos ao juiz FILIPE AUGUSTO CAETANO SANCHO.', '2026-03-17 23:23:54.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120004, 360003, '2026-03-02', 'Juntada -> Petição (Emenda à Inicial)', 'Emenda à petição inicial: correção do valor da causa de R$ 545.597,59 para R$ 54.559,76 (valor correto dos honorários). Pedido de dispensa de custas processuais conforme Lei 15.109/2025 e art. 82, §3º, CPC. Pedido de intimação solidária dos executados para pagamento em 15 dias sob pena de multa e honorários de 10% (art. 523, §1º, CPC).', '2026-03-17 23:23:54.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120005, 360003, '2026-03-02', 'Decisão -> Outras Decisões (INDEFERIMENTO)', 'DECISÃO DO JUIZ FILIPE AUGUSTO CAETANO SANCHO: INDEFERIDO o cumprimento provisório de sentença neste momento. Fundamentação: as executadas interpuseram recursos de apelação (mov. 116, 132 e 135) e NÃO HÁ INFORMAÇÕES do recebimento dos recursos até o presente momento. Entendeu que o recebimento formal é requisito para o cumprimento provisório (art. 520 CPC). Determinou: aguardar em cartório o recebimento do recurso. Após: conclusos para análise. Deferiu retificação do valor da causa conforme mov. 4.', '2026-03-17 23:23:55.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120006, 360003, '2026-03-02', 'Intimação Expedida', 'Intimação via DJEN para Paulo Da Silva Melo Filho - Polo Ativo. Referente à Mov. Decisão -> Outras Decisões (CNJ:12164).', '2026-03-17 23:23:55.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120007, 120071, '2025-06-10', 'Petição Inicial', 'Distribuição do cumprimento definitivo de sentença para cobrança de honorários advocatícios sucumbenciais', '2026-03-18 00:56:12.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120008, 120071, '2025-07-15', 'Intimação dos Executados', 'Intimação dos 4 bancos para pagamento em 15 dias sob pena de multa de 10% e honorários de 10% (art. 523, §1º, CPC)', '2026-03-18 00:56:12.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120009, 120071, '2025-09-20', 'Depósito Judicial CEF', 'Caixa Econômica Federal efetuou depósito judicial de R$ 11.762,86 - QUITADO', '2026-03-18 00:56:12.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120010, 120071, '2025-10-05', 'Alvará Expedido CEF', 'Alvará expedido para levantamento do valor depositado pela CEF - R$ 11.762,86', '2026-03-18 00:56:12.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120011, 120071, '2025-10-15', 'Bloqueio SISBAJUD Pan', 'Bloqueio via SISBAJUD de R$ 11.762,86 em conta do Banco Pan S.A. - QUITADO', '2026-03-18 00:56:12.000');
INSERT OR IGNORE INTO movimentacoes (id, processoId, data, evento, descricao, createdAt) VALUES (120012, 120071, '2026-02-24', 'Decisão de Extinção', 'Juiz julgou extinto o feito nos termos do art. 924, II, CPC. CONTRADITÓRIA: reconhece que Itaú não pagou mas extingue por quitação integral. R$ 11.762,86 do Itaú PENDENTE.', '2026-03-18 00:56:12.000');
