INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (1, 'Tese', 'Tese: AÇÃO DE OBRIGAÇÃO DE FAZER - VANDERSON OLIVEIRA DINIZ LIMA', 'Readequação dos empréstimos consignados para o limite de 35% dos proventos líquidos, conforme Lei Estadual 16.898/2010 e suas alterações (Leis Estaduais 21.063/2021 e 21.665/22), devido ao comprometimento excessivo da verba alimentar do Autor.', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DE OBRIGAÇÃO DE FAZER', NULL, 1, '2026-03-11 08:37:15.000');
