INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (7, 'Tese', 'Tese: CUMPRIMENTO PROVISÓRIO DE SENTENÇA - ARIEL ANSELMO DE OLIVEIRA', 'Cabimento do cumprimento provisório de sentença sem caução, devido à preclusão da extinção da execução e ineficácia do recurso de apelação do executado para retomar o processo executivo principal, limitando-se a controvérsia recursal à condenação em dobro, com baixo risco de reversão.', 'Tribunal de Justiça do Estado de Goiás', 'CUMPRIMENTO PROVISÓRIO DE SENTENÇA', NULL, 3, '2026-03-11 08:37:44.000');
