INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (10, 'Tese', 'Tese: AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE - O.J.S COMÉRCIO E SERVIÇOS LTDA', 'Suspensão da consolidação da propriedade fiduciária e do leilão extrajudicial do imóvel, condicionada ao depósito judicial do valor da mora, devido a indícios de abusividade contratual (juros acima da média, capitalização mensal, cumulação de encargos e financiamento de IOF com juros).', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE', NULL, 4, '2026-03-11 08:38:04.000');
