INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (13, 'Tese', 'Tese: Agravo de Instrumento - ANA TEONILA FAGUNDES DA CUNHA', 'Nulidade da execução por iliquidez e inexigibilidade do título executivo extrajudicial (Cédula de Crédito Bancário) devido à ausência de planilha discriminada do débito, inexistência de cláusula clara de vencimento antecipado e falta de interesse de agir do exequente por não diligenciar a retomada dos descontos consignados após a revogação da liminar.', 'Tribunal de Justiça do Estado de Goiás', 'Agravo de Instrumento', NULL, 5, '2026-03-11 08:38:25.000');
