INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (16, 'Tese', 'Tese: AÇÃO DECLARATÓRIA DE INEXISTÊNCIA DE DÉBITO COM PEDIDO DE TUTELA ANTECIPADA DE URGÊNCIA - MAEVE PRODUTOS HOSPITALARES LTDA', 'Inexistência de débito referente a multa e aviso prévio por rescisão contratual, alegando que a rescisão ocorreu de pleno direito devido ao término do prazo de vigência do contrato, sem prorrogação.', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DECLARATÓRIA DE INEXISTÊNCIA DE DÉBITO COM PEDIDO DE TUTELA ANTECIPADA DE URGÊNCIA', NULL, 6, '2026-03-11 08:38:41.000');
