INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (18, 'Legislacao', 'Fundamentação: AÇÃO DECLARATÓRIA DE INEXISTÊNCIA DE DÉBITO COM PEDIDO DE TUTELA ANTECIPADA DE URGÊNCIA - MAEVE PRODUTOS HOSPITALARES LTDA', 'Art. 2º e 3º do CDC (relação de consumo e inversão do ônus da prova); Art. 113 e 422 do Código Civil (boa-fé contratual); Art. 573 do Código Civil (locação por tempo determinado cessa de pleno direito); Art. 427 do Código Civil (proposta de contrato obriga o proponente); Art. 300 do CPC (tutela antecipada de urgência).', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DECLARATÓRIA DE INEXISTÊNCIA DE DÉBITO COM PEDIDO DE TUTELA ANTECIPADA DE URGÊNCIA', NULL, 6, '2026-03-11 08:38:41.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (19, 'Tese', 'Tese: AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA - STELA CARDOSO DA SILVA SANTOS', 'Readequação de empréstimos consignados que superam 35% dos proventos líquidos da Autora, em flagrante desrespeito à Lei Estadual 16.898/2010 e suas alterações, configurando comprometimento excessivo da verba alimentar.', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', NULL, 7, '2026-03-11 08:38:53.000');
