INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (27, 'Legislacao', 'Fundamentação: AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA - IRENE MARIA DOS SANTOS', 'Lei Estadual 16.898/2010 (Art. 5º, §§ 3º e 5º), Leis Estaduais 21.063/2021 e 21.665/2022 (margem consignável de 35%), Código de Defesa do Consumidor (Arts. 6º, VII, 14, 39, 51), Código de Processo Civil (Arts. 292, II, 300, 330 §2º, 334 §5º, 425 IV), Súmula 297 STJ, Súmula 60 TJ/GO, Constituição Federal (Art. 1º, III, Art. 7º, X).', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', NULL, 9, '2026-03-11 08:39:22.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (28, 'Tese', 'Tese: AÇÃO DE REPACTUAÇÃO DE DÍVIDAS com Pedido de TUTELA ANTECIPADA DE URGÊNCIA - NATALICIO LUIZ DA COSTA', 'Repactuação de dívidas por superendividamento, com base na Lei 14.871/2021 c/c artigos 54-A e seguintes do Código de Defesa do Consumidor (LEI DO SUPERENDIVIDAMENTO), devido ao comprometimento excessivo da renda (acima de 35% da margem consignável líquida).', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DE REPACTUAÇÃO DE DÍVIDAS com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', NULL, 10, '2026-03-11 08:42:41.000');
