INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (30, 'Legislacao', 'Fundamentação: AÇÃO DE REPACTUAÇÃO DE DÍVIDAS com Pedido de TUTELA ANTECIPADA DE URGÊNCIA - NATALICIO LUIZ DA COSTA', 'Lei 14.871/2021; Artigos 54-A e seguintes do CDC (Lei do Superendividamento); Artigo 292, inciso II do CPC; Artigo 98 e seguintes do CPC (Assistência Judiciária Gratuita); Art. 5º da Lei Estadual 16.898/2010; Leis Estaduais 21.063/2021 e 21.655/22; Arts. 14, 39 e 51 do CDC (Responsabilidade objetiva do fornecedor); Art. 421 do CC (Função social dos contratos); Art. 1°, inciso III, e art. 7°, inciso X, da Constituição Federal; Artigos 104-A e 104-B do CDC; Art. 300 do CPC (Tutela Antecipada).', 'Tribunal de Justiça do Estado de Goiás', 'AÇÃO DE REPACTUAÇÃO DE DÍVIDAS com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', NULL, 10, '2026-03-11 08:42:41.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (31, 'Tese', 'Tese: AÇÃO DE CUMPRIMENTO DE OBRIGAÇÃO DE FAZER com Pedido de Antecipação dos Efeitos da Tutela Específica', 'Bloqueio indevido de valores de empréstimo consignado, descumprimento de obrigação de fazer e violação da boa-fé contratual pelo banco, enquanto as parcelas são regularmente descontadas do contracheque do autor.', NULL, NULL, 'AÇÃO DE CUMPRIMENTO DE OBRIGAÇÃO DE FAZER com Pedido de Antecipação dos Efeitos da Tutela Específica', 11, '2026-03-11 09:00:03.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (32, 'Jurisprudencia', 'Jurisprudência: AÇÃO DE CUMPRIMENTO DE OBRIGAÇÃO DE FAZER com Pedido de Antecipação dos Efeitos da Tutela Específica', 'TJ-GO - APL: 01982784920138090103 MINAÇU, Relator: Des(a). GILBERTO MARQUES FILHO, Data de Julgamento: 11/02/2021, 3ª Câmara Cível, Data de Publicação: DJ de 11/02/2021 (sobre pagamento de custas ao final do processo).', NULL, NULL, 'AÇÃO DE CUMPRIMENTO DE OBRIGAÇÃO DE FAZER com Pedido de Antecipação dos Efeitos da Tutela Específica', 11, '2026-03-11 09:00:03.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (33, 'Tese', 'Tese: AÇÃO DE OBRIGAÇÃO DE FAZER', 'Ilicitude da conduta dos bancos réus por comprometimento excessivo da folha de pagamento, extrapolando a margem consignável legal de 35% e confisco de verba alimentar, em violação ao CDC e à Lei Estadual 16.898/2010 (alterada pelas Leis Estaduais 21.063/2021 e 21.665/2022).', NULL, NULL, 'AÇÃO DE OBRIGAÇÃO DE FAZER', 12, '2026-03-11 09:00:24.000');
