INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (35, 'Tese', 'Tese: AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE', 'Suspensão do procedimento de consolidação da propriedade fiduciária e leilão extrajudicial devido à controvérsia sobre o débito e indícios de abusividade contratual (juros superiores à média, capitalização irregular, encargos cumulativos e financiamento de IOF com juros), condicionada ao depósito judicial do valor originalmente intimado.', NULL, NULL, 'AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE', 4, '2026-03-11 09:00:33.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (36, 'Jurisprudencia', 'Jurisprudência: AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE', 'AgInt no CC 161.831/SP (Rel. Min. Nancy Andrighi); AgInt no REsp 1.351.544/GO (Rel. Min. Luis Felipe Salomão); AgInt no REsp 1.825.527/PR (Rel. Min. Paulo de Tarso Sanseverino).', NULL, NULL, 'AÇÃO CAUTELAR DE TUTELA DE URGÊNCIA ANTECEDENTE', 4, '2026-03-11 09:00:33.000');
INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (37, 'Tese', 'Tese: AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', 'Abusividade e ilegalidade do patamar de consignações facultativas que superam 35% da remuneração líquida, em desrespeito à Lei Estadual 16.898/2010 (alterada pelas Leis Estaduais 21.063/2021 e 21.665/2022) e ao Código de Defesa do Consumidor, configurando confisco de verba alimentar.', NULL, NULL, 'AÇÃO DE OBRIGAÇÃO DE FAZER com Pedido de TUTELA ANTECIPADA DE URGÊNCIA', 9, '2026-03-11 09:00:55.000');
