INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (150092, 'Jurisprudencia', 'Jurisprudência — Cumprimento de Sentença — 5208817-83.2024.8.09.0044', 'Jurisprudência do TJ-GO e STJ sobre a fase de cumprimento de sentença, como a exigibilidade do título executivo judicial, a aplicação de multas do art. 523, § 1º do CPC, e a possibilidade de penhora de bens. Exemplos genéricos, pois a especificidade depende do mérito da sentença: 
