INSERT OR IGNORE INTO conhecimentos (id, categoria, titulo, conteudo, tribunal, tipoAcao, tags, processoOrigemId, createdAt) VALUES (210001, 'Estrategia', 'Análise Profunda: Processo - cumprimento provisorio leonardo (SEM_mmuyob5f)', '{
