INSERT OR IGNORE INTO agente_ia_historico (id, sessaoId, userId, role, conteudo, contexto_usado, tokens_entrada, tokens_saida, createdAt) VALUES (90030, 'test_sessao_123', 1, 'assistant', 'Prezado(a) consulente,

