INSERT OR IGNORE INTO agente_ia_historico (id, sessaoId, userId, role, conteudo, contexto_usado, tokens_entrada, tokens_saida, createdAt) VALUES (90070, 'sessao_1773682973629', 1, 'assistant', 'EXCELENTÍSSIMO(A) SENHOR(A) DOUTOR(A) JUIZ(A) DE DIREITO DA [Nº DA VARA] VARA [CÍVEL/DE FAMÍLIA/ETC.] DA COMARCA DE [CIDADE] - ESTADO DE GOIÁS

