INSERT OR IGNORE INTO agente_ia_historico (id, sessaoId, userId, role, conteudo, contexto_usado, tokens_entrada, tokens_saida, createdAt) VALUES (300004, 'test_sessao_123', 1, 'assistant', 'Não encontrei a jurisprudência específica para o processo 5407476-85.2022.8.09.0051 no meu banco de dados. No entanto, a tese central do escritório sobre o limite de 35% para consignações é baseada na Lei Estadual 16.898/2010 (alterada pelas Leis 21.063/2021 e 21.665/2022). O TJ-GO tem jurisprudência consolidada nesse sentido.', '{"acoesExecutadas":[{"tool":"buscar_processo","sucesso":true}],"totalTools":1}', 0, 0, '2026-03-18 20:09:23.000');
